const addLunarDay = (
  lunarMonth: number,
  lunarDay: number,
  label: string,
  emoji: string
) => {
  const calendar = new KoreanLunarCalendar();

  calendar.setLunarDate(
    year,
    lunarMonth,
    lunarDay,
    false
  );

  const solar = calendar.getSolarCalendar();

  lunarDays[`${solar.month}-${solar.day}`] = {
    label,
    type: "anniversary",
    emoji,
  };
};

