function getSeason(month: number): { name: string; emoji: string } {
  if (month >= 3 && month <= 5) return { name: "봄", emoji: "🌸" };
  if (month >= 6 && month <= 8) return { name: "여름", emoji: "☀️" };
  if (month >= 9 && month <= 11) return { name: "가을", emoji: "🍂" };
  return { name: "겨울", emoji: "❄️" };
}

function getSeasonGreeting(month: number): string {
  if (month >= 3 && month <= 5) {
    const greetings = [
      "따뜻한 봄 기운이 완연한 요즘",
      "봄꽃이 활짝 핀 아름다운 계절에",
      "포근한 봄 날씨가 이어지는 요즘",
    ];
    return greetings[Math.floor(Math.random() * greetings.length)];
  }
  if (month >= 6 && month <= 8) {
    const greetings = [
      "무더운 여름이 한창인 요즘",
      "뜨거운 햇살이 내리쬐는 이 계절에",
      "더위가 기승을 부리는 요즘",
    ];
    return greetings[Math.floor(Math.random() * greetings.length)];
  }
  if (month >= 9 && month <= 11) {
    const greetings = [
      "선선한 가을 바람이 불어오는 요즘",
      "단풍이 물드는 아름다운 계절에",
      "높고 푸른 하늘이 펼쳐지는 가을에",
    ];
    return greetings[Math.floor(Math.random() * greetings.length)];
  }
  const greetings = [
    "차가운 겨울 바람이 부는 요즘",
    "포근한 실내가 그리운 겨울에",
    "한파가 이어지는 추운 날씨에",
  ];
  return greetings[Math.floor(Math.random() * greetings.length)];
}

